<title>Appreciation — Mrs. Philomena Korley</title>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,600;1,300;1,400&family=Cinzel:wght@400;600;800&family=Lato:wght@300;400&display=swap" rel="stylesheet">
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
–gold: #C9A84C;
–gold-light: #E8CC80;
–gold-pale: #F5E9C4;
–cream: #FAF6EE;
–dark: #1A1208;
–mid: #3D2B0A;
–accent: #7B3F00;
}

html { scroll-behavior: smooth; }

body {
background-color: var(–dark);
color: var(–cream);
font-family: ‘Lato’, sans-serif;
font-weight: 300;
overflow-x: hidden;
min-height: 100vh;
}

/* === STARFIELD BG === */
.stars {
position: fixed;
inset: 0;
z-index: 0;
pointer-events: none;
overflow: hidden;
}
.stars span {
position: absolute;
width: 2px;
height: 2px;
background: var(–gold-light);
border-radius: 50%;
opacity: 0;
animation: twinkle var(–dur, 4s) var(–delay, 0s) infinite ease-in-out;
}
@keyframes twinkle {
0%, 100% { opacity: 0; transform: scale(0.5); }
50% { opacity: var(–op, 0.6); transform: scale(1.2); }
}

/* === GOLD ORBS === */
.orb {
position: fixed;
border-radius: 50%;
filter: blur(80px);
pointer-events: none;
z-index: 0;
}
.orb-1 {
width: 500px; height: 500px;
background: radial-gradient(circle, rgba(201,168,76,0.18) 0%, transparent 70%);
top: -100px; left: -100px;
animation: drift1 12s ease-in-out infinite alternate;
}
.orb-2 {
width: 400px; height: 400px;
background: radial-gradient(circle, rgba(201,168,76,0.12) 0%, transparent 70%);
bottom: 0; right: -100px;
animation: drift2 15s ease-in-out infinite alternate;
}
@keyframes drift1 { to { transform: translate(60px, 80px); } }
@keyframes drift2 { to { transform: translate(-60px, -60px); } }

/* === PAGE WRAPPER === */
.page {
position: relative;
z-index: 1;
min-height: 100vh;
display: flex;
flex-direction: column;
align-items: center;
}

/* === HEADER CROWN === */
.crown-header {
width: 100%;
text-align: center;
padding: 56px 24px 24px;
animation: fadeDown 1.2s ease both;
}
@keyframes fadeDown {
from { opacity: 0; transform: translateY(-30px); }
to { opacity: 1; transform: translateY(0); }
}
.crown-label {
font-family: ‘Cinzel’, serif;
font-size: clamp(10px, 1.5vw, 13px);
letter-spacing: 0.35em;
color: var(–gold);
text-transform: uppercase;
margin-bottom: 10px;
opacity: 0.85;
}
.divider-line {
display: flex;
align-items: center;
justify-content: center;
gap: 12px;
margin: 18px auto;
}
.divider-line span.line {
display: block;
height: 1px;
width: clamp(60px, 12vw, 160px);
background: linear-gradient(90deg, transparent, var(–gold), transparent);
}
.divider-line span.diamond {
display: block;
width: 7px; height: 7px;
background: var(–gold);
transform: rotate(45deg);
flex-shrink: 0;
}

/* === HERO SECTION === */
.hero {
width: 100%;
max-width: 1100px;
margin: 0 auto;
padding: 0 24px 60px;
display: grid;
grid-template-columns: 1fr 1fr;
gap: 60px;
align-items: center;
animation: fadeUp 1.4s 0.3s ease both;
}
@keyframes fadeUp {
from { opacity: 0; transform: translateY(40px); }
to { opacity: 1; transform: translateY(0); }
}

/* === PHOTO FRAME === */
.photo-container {
position: relative;
display: flex;
justify-content: center;
}
.photo-frame-outer {
position: relative;
padding: 5px;
background: linear-gradient(145deg, var(–gold), var(–gold-light), var(–gold), #8B6914);
border-radius: 4px;
box-shadow:
0 0 0 1px rgba(201,168,76,0.3),
0 20px 60px rgba(0,0,0,0.7),
0 0 80px rgba(201,168,76,0.15),
inset 0 0 20px rgba(201,168,76,0.1);
animation: glowPulse 4s ease-in-out infinite;
}
@keyframes glowPulse {
0%, 100% { box-shadow: 0 0 0 1px rgba(201,168,76,0.3), 0 20px 60px rgba(0,0,0,0.7), 0 0 60px rgba(201,168,76,0.12), inset 0 0 20px rgba(201,168,76,0.08); }
50% { box-shadow: 0 0 0 1px rgba(201,168,76,0.5), 0 20px 60px rgba(0,0,0,0.7), 0 0 100px rgba(201,168,76,0.25), inset 0 0 20px rgba(201,168,76,0.15); }
}
.photo-frame-inner {
border-radius: 2px;
overflow: hidden;
line-height: 0;
position: relative;
}
.photo-frame-inner::after {
content: ‘’;
position: absolute;
inset: 0;
background: linear-gradient(180deg, transparent 60%, rgba(26,18,8,0.5) 100%);
pointer-events: none;
}
.hero-photo {
display: block;
width: 100%;
max-width: 420px;
height: auto;
object-fit: cover;
}

/* Corner ornaments */
.corner {
position: absolute;
width: 30px; height: 30px;
border-color: var(–gold-light);
border-style: solid;
opacity: 0.7;
}
.corner-tl { top: -8px; left: -8px; border-width: 2px 0 0 2px; }
.corner-tr { top: -8px; right: -8px; border-width: 2px 2px 0 0; }
.corner-bl { bottom: -8px; left: -8px; border-width: 0 0 2px 2px; }
.corner-br { bottom: -8px; right: -8px; border-width: 0 2px 2px 0; }

/* === TEXT SIDE === */
.hero-text {
display: flex;
flex-direction: column;
gap: 28px;
}
.appreciation-tag {
font-family: ‘Cinzel’, serif;
font-size: clamp(9px, 1.1vw, 11px);
letter-spacing: 0.45em;
color: var(–gold);
text-transform: uppercase;
}
.hero-name {
font-family: ‘Cinzel’, serif;
font-size: clamp(26px, 4vw, 52px);
font-weight: 800;
line-height: 1.1;
color: var(–cream);
text-shadow: 0 0 40px rgba(201,168,76,0.3);
}
.hero-name .prefix {
display: block;
font-size: 0.52em;
font-weight: 400;
color: var(–gold);
letter-spacing: 0.1em;
margin-bottom: 4px;
}
.quote-block {
position: relative;
padding: 28px 28px 28px 36px;
border-left: 3px solid var(–gold);
background: rgba(201,168,76,0.04);
}
.quote-block::before {
content: ‘\201C’;
font-family: ‘Cormorant Garamond’, serif;
font-size: 100px;
line-height: 0;
color: var(–gold);
opacity: 0.18;
position: absolute;
top: 40px;
left: 8px;
}
.quote-text {
font-family: ‘Cormorant Garamond’, serif;
font-size: clamp(16px, 2vw, 22px);
font-weight: 300;
font-style: italic;
line-height: 1.75;
color: var(–gold-pale);
position: relative;
z-index: 1;
}
.quote-text strong {
font-style: normal;
font-weight: 600;
color: var(–gold-light);
}
.food-badges {
display: flex;
flex-wrap: wrap;
gap: 10px;
}
.badge {
font-family: ‘Cinzel’, serif;
font-size: 10px;
letter-spacing: 0.2em;
color: var(–gold);
border: 1px solid rgba(201,168,76,0.4);
padding: 6px 14px;
background: rgba(201,168,76,0.06);
text-transform: uppercase;
position: relative;
overflow: hidden;
transition: all 0.3s ease;
cursor: default;
}
.badge::after {
content: ‘’;
position: absolute;
inset: 0;
background: linear-gradient(135deg, rgba(201,168,76,0.1) 0%, transparent 60%);
opacity: 0;
transition: opacity 0.3s;
}
.badge:hover { border-color: var(–gold); background: rgba(201,168,76,0.14); }
.badge:hover::after { opacity: 1; }

/* === SIGNATURE / FROM === */
.from-section {
text-align: right;
padding-top: 10px;
border-top: 1px solid rgba(201,168,76,0.2);
}
.from-label {
font-family: ‘Lato’, sans-serif;
font-size: 11px;
letter-spacing: 0.3em;
color: var(–gold);
text-transform: uppercase;
opacity: 0.7;
margin-bottom: 4px;
}
.from-name {
font-family: ‘Cormorant Garamond’, serif;
font-size: clamp(20px, 2.5vw, 28px);
font-weight: 600;
font-style: italic;
color: var(–cream);
}

/* === FOOTER ORNAMENT === */
.footer-ornament {
width: 100%;
text-align: center;
padding: 30px 24px 50px;
animation: fadeUp 1.4s 0.8s ease both;
}
.footer-text {
font-family: ‘Cinzel’, serif;
font-size: 10px;
letter-spacing: 0.5em;
color: var(–gold);
opacity: 0.4;
text-transform: uppercase;
}

/* === RESPONSIVE === */
@media (max-width: 720px) {
.hero {
grid-template-columns: 1fr;
gap: 40px;
text-align: center;
}
.from-section { text-align: center; }
.quote-block { padding-left: 24px; }
.food-badges { justify-content: center; }
.hero-photo { max-width: 320px; }
.corner { display: none; }
}
</style>

</head>
<body>

